compile.workshop:
variables {
    global:
        0: arr
        1: result
}

rule ("capture directive without size optimization") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Index Of Array Value(Global.arr, 0));
    }
}

//Optimize for size enabled
rule ("literal slots precede capture replacement") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(result, Index Of Array Value(Global.arr, Null));
        Set Global Variable(result, Index Of Array Value(Global.arr, 1));
        Set Global Variable(result, Array Contains(Global.arr, Null));
        Set Global Variable(result, Index Of Array Value(Global.arr, Index Of Array Value(Global.arr, Null)));
        Wait(False, Ignore Condition);
        Create HUD Text(All Players(All Teams), Point Capture Percentage, Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
    }
}

